import { createConnection, Socket } from 'net';
import { EventEmitter } from 'events';
import { randomInt } from 'crypto';

interface CacheEntry {
  key: string;
  value: Buffer;
  ttl: number;
}

interface RateLimitState {
  tokens: number;
  lastRefill: number;
  maxTokens: number;
  refillRate: number;
}

class DistributedCacheClient extends EventEmitter {
  private socket: Socket | null = null;
  private responseBuffer: Buffer;
  private bufferOffset: number = 0;
  private readonly maxBufferSize: number;
  private rateLimiter: RateLimitState;
  private retryCount: number = 0;
  private readonly maxRetries: number = 3;
  private pendingCallbacks: Map<string, (err: Error | null, data?: Buffer) => void>;

  constructor(private host: string, private port: number, options?: { maxBuffer?: number; rateLimit?: number }) {
    super();
    this.maxBufferSize = options?.maxBuffer || 4096;
    this.responseBuffer = Buffer.alloc(this.maxBufferSize);
    this.rateLimiter = {
      tokens: options?.rateLimit || 100,
      lastRefill: Date.now(),
      maxTokens: options?.rateLimit || 100,
      refillRate: 10
    };
    this.pendingCallbacks = new Map();
  }

  private refillTokens(): void {
    const now = Date.now();
    const elapsed = (now - this.rateLimiter.lastRefill) / 1000;
    const newTokens = Math.floor(elapsed * this.rateLimiter.refillRate);
    this.rateLimiter.tokens = Math.min(
      this.rateLimiter.maxTokens,
      this.rateLimiter.tokens + newTokens
    );
    this.rateLimiter.lastRefill = now;
  }

  private consumeToken(): boolean {
    this.refillTokens();
    if (this.rateLimiter.tokens > 0) {
      this.rateLimiter.tokens--;
      return true;
    }
    return false;
  }

  private generateRequestId(): number {
    // Use cryptographically strong randomness to avoid predictable/colliding IDs.
    return randomInt(0, 0xFFFFFFFF);
  }

  async connect(): Promise<void> {
    return new Promise((resolve, reject) => {
      this.socket = createConnection({ host: this.host, port: this.port }, () => {
        this.retryCount = 0;
        resolve();
      });

      this.socket.on('data', (chunk: Buffer) => this.handleIncomingData(chunk));
      this.socket.on('error', (err) => this.handleError(err, reject));
      this.socket.on('close', () => this.handleDisconnect());
    });
  }

  private handleIncomingData(chunk: Buffer): void {
    const headerSize = 8;
    let chunkOffset = 0;

    while (chunkOffset < chunk.length) {
      if (this.bufferOffset < headerSize && chunkOffset < chunk.length) {
        const headerBytesNeeded = headerSize - this.bufferOffset;
        const headerBytesAvailable = Math.min(headerBytesNeeded, chunk.length - chunkOffset);
        chunk.copy(this.responseBuffer, this.bufferOffset, chunkOffset, chunkOffset + headerBytesAvailable);
        this.bufferOffset += headerBytesAvailable;
        chunkOffset += headerBytesAvailable;
      }

      if (this.bufferOffset >= headerSize) {
        const messageLength = this.responseBuffer.readUInt32BE(0);
        const requestId = this.responseBuffer.readUInt32BE(4);

        const totalFrameSize = headerSize + messageLength;

        if (totalFrameSize > this.maxBufferSize) {
          // Reject oversized messages - reset state and skip
          this.bufferOffset = 0;
          this.emit('error', new Error(`Message size ${totalFrameSize} exceeds maximum ${this.maxBufferSize}`));
          return;
        }

        // Calculate available payload bytes after validation
        const payloadBytesNeeded = totalFrameSize - this.bufferOffset;
        const payloadBytesAvailable = Math.min(payloadBytesNeeded, chunk.length - chunkOffset);

        // Copy available payload bytes - buffer is guaranteed to have capacity
        chunk.copy(this.responseBuffer, this.bufferOffset, chunkOffset, chunkOffset + payloadBytesAvailable);
        this.bufferOffset += payloadBytesAvailable;
        chunkOffset += payloadBytesAvailable;

        if (this.bufferOffset >= totalFrameSize) {
          this.processCompleteMessage(requestId, this.responseBuffer.slice(headerSize, totalFrameSize));
          this.bufferOffset = 0;
        }
      }
    }
  }

  private processCompleteMessage(requestId: number, payload: Buffer): void {
    const callbackKey = requestId.toString();
    const callback = this.pendingCallbacks.get(callbackKey);
    if (callback) {
      this.pendingCallbacks.delete(callbackKey);
      // Guard against empty payloads to avoid out-of-bounds read.
      if (payload.length < 1) {
        callback(new Error('Malformed response: empty payload'));
        return;
      }
      const statusCode = payload.readUInt8(0);
      if (statusCode === 0) {
        callback(null, payload.slice(1));
      } else {
        callback(new Error(`Cache error: status ${statusCode}`));
      }
    }
  }

  private handleError(err: Error, reject?: (reason?: any) => void): void {
    if (this.retryCount < this.maxRetries) {
      this.retryCount++;
      const backoff = Math.pow(2, this.retryCount) * 100;
      setTimeout(() => this.reconnect(), backoff);
    } else {
      this.emit('error', err);
      if (reject) reject(err);
    }
  }

  private async reconnect(): Promise<void> {
    try {
      await this.connect();
      this.emit('reconnected');
    } catch (err) {
      this.handleError(err as Error);
    }
  }

  private handleDisconnect(): void {
    this.socket = null;
    this.bufferOffset = 0;
    this.emit('disconnected');
  }

  async get(key: string): Promise<Buffer | null> {
    if (!this.consumeToken()) {
      throw new Error('Rate limit exceeded');
    }

    return new Promise((resolve, reject) => {
      const requestId = this.generateRequestId();
      const keyBuf = Buffer.from(key, 'utf8');
      const header = Buffer.alloc(8);
      header.writeUInt32BE(1 + keyBuf.length, 0); // message length
      header.writeUInt32BE(requestId, 4);
      const command = Buffer.from([0x01]); // GET command
      const frame = Buffer.concat([header, command, keyBuf]);

      this.pendingCallbacks.set(requestId.toString(), (err, data) => {
        if (err) reject(err);
        else resolve(data || null);
      });

      this.socket?.write(frame);
    });
  }

  async set(key: string, value: Buffer, ttl: number = 3600): Promise<void> {
    if (!this.consumeToken()) {
      throw new Error('Rate limit exceeded');
    }

    return new Promise((resolve, reject) => {
      const requestId = this.generateRequestId();
      const keyBuf = Buffer.from(key, 'utf8');
      const ttlBuf = Buffer.alloc(4);
      ttlBuf.writeUInt32BE(ttl, 0);
      const keyLenBuf = Buffer.alloc(2);
      keyLenBuf.writeUInt16BE(keyBuf.length, 0);

      const header = Buffer.alloc(8);
      header.writeUInt32BE(1 + 2 + keyBuf.length + 4 + value.length, 0);
      header.writeUInt32BE(requestId, 4);
      const command = Buffer.from([0x02]); // SET command
      const frame = Buffer.concat([header, command, keyLenBuf, keyBuf, ttlBuf, value]);

      this.pendingCallbacks.set(requestId.toString(), (err) => {
        if (err) reject(err);
        else resolve();
      });

      this.socket?.write(frame);
    });
  }

  disconnect(): void {
    this.socket?.destroy();
    this.socket = null;
    this.pendingCallbacks.clear();
  }
}

export { DistributedCacheClient, CacheEntry, RateLimitState };
